<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use App\Models\Concerns\BelongsToSchool; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class ReportCard extends Model { use BelongsToSchool; protected $fillable=['student_id','academic_period_id','version','general_average','rank','appreciation','verification_token','published_at','published_by']; protected function casts():array{return ['general_average'=>'decimal:2','published_at'=>'datetime'];} public function student():BelongsTo{return $this->belongsTo(Student::class);} public function period():BelongsTo{return $this->belongsTo(AcademicPeriod::class,'academic_period_id');} public function items():HasMany{return $this->hasMany(ReportCardItem::class);} }
